varying vec3 tint;

void vertex() {
	tint = vec3(UV.x, UV.y, 1.0 - UV.x);
}

void fragment() {
	COLOR = vec4(tint, 1.0);
}

shader_type canvas_item;

varying flat vec3 tint;

void vertex() {
	tint = vec3(UV.x, UV.y, 1.0 - UV.x);
}

void fragment() {
	COLOR = vec4(tint, 1.0);
}

shader_type canvas_item;

varying float fold;

void vertex() {
	float phase = UV.x * 8.0 - TIME * 3.0;
	VERTEX.y += sin(phase) * 24.0 * UV.x;
	fold = cos(phase) * UV.x;
}

void fragment() {
	COLOR.rgb *= 0.9 + 0.1 * fold;
}

shader_type canvas_item;

uniform float amplitude = 24.0;
uniform float frequency = 8.0;
uniform float speed = 3.0;

void vertex() {
	float phase = UV.x * frequency - TIME * speed;
	VERTEX.y += sin(phase) * amplitude * UV.x;
	COLOR.rgb *= 0.9 + 0.1 * cos(phase) * UV.x;
}

shader_type canvas_item;

varying float stripe;

void vertex() {
	stripe = sin(UV.x * TAU * 6.0);
}

void fragment() {
	COLOR.rgb *= 0.75 + 0.25 * stripe;
}
